fn decode_simd3reg_ext(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xffb00010 != 0xf2b00000 {
        return Err(DecodeError::Unallocated);
    }
    // 111100101|D=x|11|Vn=xxxx|Vd=xxxx|imm4=xxxx|N=x|Q=x|M=x|0|Vm=xxxx
    let Vn: u8 = ((bits >> 16) & 0xf) as u8;
    let Vd: u8 = ((bits >> 12) & 0xf) as u8;
    let Vm: u8 = (bits & 0xf) as u8;
    let imm4: u8 = ((bits >> 8) & 0xf) as u8;
    let D: u8 = ((bits >> 22) & 0x1) as u8;
    let N: u8 = ((bits >> 7) & 0x1) as u8;
    let M: u8 = ((bits >> 5) & 0x1) as u8;
    match bits & 0x40 {
        0 => {
            // VEXT (byte elements) — 64-bit SIMD vector
            // VEXT{<c>}{<q>}.8  {<Dd>, }<Dn>, <Dm>, #<imm>
            if imm4 >> 3 == 0b1 {
                shadow::Undefined()?;
            }
            Ok(Instruction::VextA1D {
                Dd: DReg::new(D << 4 | Vd),
                Dn: DReg::new(N << 4 | Vn),
                Dm: DReg::new(M << 4 | Vm),
                imm: imm4,
            })
        }
        64 => {
            // VEXT (byte elements) — 128-bit SIMD vector
            // VEXT{<c>}{<q>}.8  {<Qd>, }<Qn>, <Qm>, #<imm>
            if Vd & 0x1 == 0b1 || Vn & 0x1 == 0b1 || Vm & 0x1 == 0b1 {
                shadow::Undefined()?;
            }
            Ok(Instruction::VextA1Q {
                Qd: QReg::new((D << 4 | Vd) >> 1),
                Qn: QReg::new((N << 4 | Vn) >> 1),
                Qm: QReg::new((M << 4 | Vm) >> 1),
                imm: imm4,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

